langs = ["es", "tr", "hi", "pt-BR", "ru"]
out = {"sourceLanguage": "en", "version": "1.0", "strings": {}}
for k, vals in T.items():
    loc = {}
    for code, v in zip(langs, vals):
        loc[code] = {"stringUnit": {"state": "translated", "value": v}}
    out["strings"][k] = {"localizations": loc}

path = os.path.join(os.path.dirname(__file__), "..", "ios", "RoomScan", "Resources", "Localizable.xcstrings")
with open(path, "w", encoding="utf-8") as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
print("wrote", len(T), "keys →", os.path.normpath(path))
